type Shape = | Circle(r: Int, d: Int) | Dot

fn size(s: Shape) -> Int {
    match s {
        Circle(r: x, y) => x    // ✗ one named binding, one positional
        Dot => 0
    }
}

fn size(s: Shape) -> Int {
    match s {
        Circle(x, y) => x       // ✓ all positional
        Dot => 0
    }
}
